failure.message:
  Expected: String containing "BattleResultController"
  But was:  "// 역할: 플레이어의 소환, 리롤, 공격, 턴 종료 흐름을 조율한다.
public class PlayerActionFlow
{
    private readonly PlayerController player;
    private readonly SummonController summonController;
    private readonly BattleController battleController;
    private readonly PlayerTurnActions turnActions;
    private readonly PlayerSummonActions summonActions;
    private readonly PlayerAttackActions attackActions;
    private readonly PlayerView playerView;
    private readonly PlayerFeedbackView feedbackView;
    private readonly PlayerTurnResourceState resourceState;
    private readonly PlayerTurnProgressState turnProgressState;

    public PlayerActionFlow(
        PlayerController player,
        SummonController summonController,
        BattleController battleController,
        PlayerTurnResourceState resourceState,
        PlayerTurnProgressState turnProgressState,
        PlayerTurnActions turnActions,
        PlayerSummonActions summonActions,
        PlayerAttackActions attackActions,
        PlayerView playerView,
        PlayerFeedbackView feedbackView)
    {
        this.player = player;
        this.summonController = summonController;
        this.battleController = battleController;
        this.resourceState = resourceState;
        this.turnProgressState = turnProgressState;
        this.turnActions = turnActions;
        this.summonActions = summonActions;
        this.attackActions = attackActions;
        this.playerView = playerView;
        this.feedbackView = feedbackView;
    }

    public int GetClearTurn()
    {
        int clearTurn = turnActions.GetPlayerClearTurn();
        turnProgressState.SetTurnProgress(clearTurn, player.currentTurn);
        return clearTurn;
    }

    public void ResetPlayerSetting()
    {
        resourceState.Reset();
        UpdateManaUI();
    }

    public void UpdateRedrawButtonState()
    {
        if (!resourceState.CanRedraw())
        {
            playerView.ShowRedrawButtonDisabled();
            return;
        }

        playerView.ShowRedrawButtonEnabled();
    }

    public void StartPlayerTurn()
    {
        feedbackView.Log("플레이어 턴 시작");
        feedbackView.Log($"{player.gameObject.name} 의 마나: {resourceState.Mana}");
        turnActions.StartPlayerTurn(turnProgressState);
        player.clearTurn = turnProgressState.ClearTurn;
        player.currentTurn = turnProgressState.CurrentTurn;
        resourceState.StartTurn();
        UpdateManaUI();
        BattleFailResultTry();
    }

    public void TryStartSummon()
    {
        if (PlayerActionBlockedCheck()) return;

        summonActions.TryStartSummon();
    }

    public void TryEndPlayerTurn()
    {
        if (PlayerActionBlockedCheck()) return;

        if (!turnActions.TryEndPlayerTurn())
        {
            feedbackView.PlayFail();
            feedbackView.Log("플레이어 턴이 아닙니다.");
            return;
        }

        feedbackView.Log("플레이어 턴 종료");
        feedbackView.PlayClick();
    }

    public void TryStartRedraw()
    {
        if (PlayerActionBlockedCheck()) return;

        summonActions.TryStartRedraw();
    }

    public void TryExecuteNormalAttack()
    {
        if (PlayerActionBlockedCheck()) return;

        attackActions.TryExecuteNormalAttack();
    }

    public void TryExecuteSpecialAttack()
    {
        if (PlayerActionBlockedCheck()) return;

        attackActions.TryExecuteSpecialAttack();
    }

    public void SetHasSummonedThisTurn(bool value)
    {
        resourceState.SetHasSummonedThisTurn(value);
    }

    public bool HasSummonedThisTurn()
    {
        return resourceState.HasSummonedThisTurn;
    }

    public void UpdateManaUI()
    {
        playerView.UpdateMana(resourceState.Mana, resourceState.CanShowSummonAvailable());
    }

    public void AddMana()
    {
        resourceState.AddMana(10);
        UpdateManaUI();
    }

    public void SetSelectedPlateIndex(int selectedPlateIndex)
    {
        attackActions.SetSelectedPlateIndex(selectedPlateIndex);
    }

    public void BattleFailResultTry()
    {
        turnActions.CheckPlayerFailResult(turnProgressState);
    }

    private bool PlayerActionBlockedCheck()
    {
        return summonController.IsSummoning() || battleController.GetIsAttacking();
    }
}
"

  Expected: String containing "private List<Plate> GetSpecialAttackTargetPlates(IAttackStrategy attackStrategy, bool isPlayer)"
  But was:  "using UnityEngine;

// 역할: 선택된 소환수의 공격 시작 상태를 관리하고 특수 공격을 실제 공격 전략으로 실행한다.
public class BattleController : MonoBehaviour
{

    [SerializeField] private SummonStatePanelView statePanel;

    public bool isAttacking = false; //공격중인이 판별

    private PlateController plateController;
    private BattleSpecialAttackExecutor specialAttackExecutor;
    private readonly BattleAttackState attackState = new BattleAttackState();

    public Summon GetAttackingSummon()
    {
        return attackState.AttackingSummon;
    }

    void Awake()
    {
        plateController = GetComponent<PlateController>();
        specialAttackExecutor = new BattleSpecialAttackExecutor(plateController);
    }

    public Summon AttackStart(int buttonIndex)
    {
        attackState.StartAttack(statePanel.GetStatePanelSummon());

        if (attackState.AttackingSummon == null)
        {
            Debug.Log("선택된 plate에 소환수가 없습니다.");
            return null;
        }

        if (IsValidSpecialAttackIndex(attackState.AttackingSummon, buttonIndex))
        {
            attackState.SetCurrentSpecialAttackInfo(
                new SpecialAttackInfo(
                    attackState.AttackingSummon.GetSpecialAttackStrategy()[buttonIndex],
                    buttonIndex));
        }
        return attackState.AttackingSummon;
    }

    public void SpecialAttackExecute(Summon attackSummon, int selectedPlateIndex, int selectSpecialAttackIndex, bool isPlayer = false)
    {
        if (!specialAttackExecutor.Execute(
            attackSummon,
            selectedPlateIndex,
            selectSpecialAttackIndex,
            isPlayer))
        {
            return;
        }

        BattleAttackStateReset();
    }

    private bool IsValidSpecialAttackIndex(Summon attackSummon, int selectSpecialAttackIndex)
    {
        if (attackSummon == null || attackSummon.GetSpecialAttackStrategy() == null)
        {
            return false;
        }

        return selectSpecialAttackIndex >= 0 && selectSpecialAttackIndex < attackSummon.GetSpecialAttackStrategy().Length;
    }

    public void BattleAttackStateReset()
    {
        attackState.Reset();
        isAttacking = attackState.IsAttacking;
        plateController.ResetAllPlateHighlight();
    }


    public PlateController GetPlateController()
    {
        return plateController;
    }

    public SpecialAttackInfo GetCurrentSpecialAttackInfo()
    {
        return attackState.CurrentSpecialAttackInfo;
    }

    public bool HasCurrentSpecialAttackInfo()
    {
        return attackState.HasCurrentSpecialAttackInfo();
    }

    public int GetCurrentSpecialAttackInfoIndex()
    {
        return attackState.GetCurrentSpecialAttackInfoIndex();
    }

    public bool DoesCurrentSpecialAttackTargetPlayerPlate()
    {
        return attackState.DoesCurrentSpecialAttackTargetPlayerPlate();
    }

    public bool GetIsAttacking()
    {
        return attackState.IsAttacking;
    }
    public void SetIsAttacking(bool isAttacking)
    {
        attackState.SetIsAttacking(isAttacking);
        this.isAttacking = attackState.IsAttacking;
    }
}
"

