  Expected: String containing "actionController.TryExecuteSpecialAttack();"
  But was:  "using System.Collections.Generic;
using UnityEngine;
using UnityEngine.UI;

// 역할: Unity 이벤트와 씬 연결을 유지하고 플레이어 행동, UI, 피드백 책임을 연결한다.
public class PlayerController : MonoBehaviour
{
    [Header("마나UI")]
    [SerializeField] private List<RawImage> manaList;

    [Header("마나텍스쳐")]
    [SerializeField] private Texture notHaveTexture;
    [SerializeField] private Texture haveTexture;

    [Header("버튼 UI")]
    [SerializeField] private Button summonButton;
    [SerializeField] private Button reSummonButton;

    [Header("상태창 패널")]
    [SerializeField] private Image statePanel;

    [Header("효과음")]
    [SerializeField] private AudioSource clickSound;
    [SerializeField] private AudioSource failSound;

    [Header("컨트롤러")]
    [SerializeField] private SummonController summonController;
    [SerializeField] private TurnController turnController;
    [SerializeField] private BattleController battleController;
    [SerializeField] private PlateController plateController;
    [SerializeField] private BattleResultController battleResultController;

    private PlayerActionFlow actionFlow;
    private PlayerView playerView;
    private PlayerFeedbackView feedbackView;

    public int currentTurn;
    public int clearTurn;

    private void Awake()
    {
        EnsureBattleResultController();

        playerView = new PlayerView(
            manaList,
            notHaveTexture,
            haveTexture,
            summonButton,
            reSummonButton,
            statePanel);

        feedbackView = new PlayerFeedbackView(clickSound, failSound);
        var resourceState = new PlayerTurnResourceState();
        var turnProgressState = new PlayerTurnProgressState();
        var turnActions = new PlayerTurnActions(
            turnController,
            battleResultController);
        var actionExecutor = new PlayerActionExecutor();
        var summonActions = new PlayerSummonActions(
            summonController,
            plateController,
            resourceState,
            actionExecutor,
            playerView,
            feedbackView);
        var attackActions = new PlayerAttackActions(
            this,
            summonController,
            battleController,
            plateController,
            turnProgressState,
            turnActions,
            playerView,
            feedbackView,
            actionExecutor);

        actionFlow = new PlayerActionFlow(
            this,
            summonController,
            battleController,
            resourceState,
            turnProgressState,
            turnActions,
            summonActions,
            attackActions,
            playerView,
            feedbackView);

        clearTurn = actionFlow.GetClearTurn();
        actionFlow.ResetPlayerSetting();
    }

    private void Update()
    {
        actionFlow.UpdateRedrawButtonState();
    }

    public void PlayerTurnStart()
    {
        actionFlow.StartPlayerTurn();
    }

    public void OnSummonBtnClick()
    {
        actionFlow.TryStartSummon();
    }

    public void PlayerTurnOverBtn()
    {
        actionFlow.TryEndPlayerTurn();
    }

    public void OnRedrawButtonClick()
    {
        actionFlow.TryStartRedraw();
    }

    public void OnAttackBtnClick()
    {
        actionFlow.TryExecuteNormalAttack();
    }

    public void OnSpecialAttackBtnClick()
    {
        actionFlow.TryExecuteSpecialAttack();
    }

    public void SetHasSummonedThisTurn(bool value)
    {
        actionFlow.SetHasSummonedThisTurn(value);
    }

    public bool HasSummonedThisTurn()
    {
        return actionFlow.HasSummonedThisTurn();
    }

    public void UpdateManaUI()
    {
        actionFlow.UpdateManaUI();
    }

    public void AddMana()
    {
        actionFlow.AddMana();
    }

    public void SetSelectedPlateIndex(int selectedPlateIndex)
    {
        actionFlow.SetSelectedPlateIndex(selectedPlateIndex);
    }

    public void TurnOver()
    {
        actionFlow.BattleFailResultTry();
    }

    private void EnsureBattleResultController()
    {
        if (battleResultController != null)
        {
            return;
        }

        battleResultController = GetComponent<BattleResultController>();
        if (battleResultController == null)
        {
            battleResultController = gameObject.AddComponent<BattleResultController>();
        }
    }
}
"

